public class StringMutability{public static void main(String[]x){String a="Java",b=a.concat(" Programming");System.out.println("Original String = "+a);System.out.println("New String = "+b);StringBuffer c=new StringBuffer("Java");c.append(" Programming");System.out.println("StringBuffer = "+c);StringBuilder d=new StringBuilder("Java");d.append(" Programming");System.out.println("StringBuilder = "+d);}}